From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 22:28:35 +0100
Subject: [PATCH] plugins/colorpicker: show a magnifier while picking a color

The cursor covers the pixel being picked, so there was no way to see which
exact pixel would be chosen. While picking, the cursor is now replaced by a
loupe showing the nearby pixels enlarged, with the picked one outlined.

BUG: 372921
---
 src/plugins/colorpicker/colorpicker.cpp | 140 ++++++++++++++++++++++++
 src/plugins/colorpicker/colorpicker.h   |   6 +
 2 files changed, 146 insertions(+)

diff --git a/src/plugins/colorpicker/colorpicker.cpp b/src/plugins/colorpicker/colorpicker.cpp
index 9caed90b89..2d9e488ba2 100644
--- a/src/plugins/colorpicker/colorpicker.cpp
+++ b/src/plugins/colorpicker/colorpicker.cpp
@@ -31,6 +31,7 @@
 #include <KLocalizedString>
 #include <QDBusConnection>
 #include <QDBusMetaType>
+#include <QVector2D>

 Q_DECLARE_METATYPE(QColor)

@@ -55,6 +56,54 @@ const QDBusArgument &operator>>(const QDBusArgument &argument, QColor &color)
 namespace KWin
 {

+static const int s_loupeRadius = 6;
+static const int s_loupeCellSize = 10;
+
+static void renderOutline(const RenderViewport &viewport, const RectF &rect, qreal width, const QColor &color)
+{
+    const RectF outer = rect.scaled(viewport.scale());
+    const RectF inner = rect.adjusted(width, width, -width, -width).scaled(viewport.scale());
+    const QList<QVector2D> verts{
+        // top
+        QVector2D(outer.left(), outer.top()),
+        QVector2D(outer.right(), outer.top()),
+        QVector2D(outer.right(), inner.top()),
+        QVector2D(outer.right(), inner.top()),
+        QVector2D(outer.left(), inner.top()),
+        QVector2D(outer.left(), outer.top()),
+        // bottom
+        QVector2D(outer.left(), inner.bottom()),
+        QVector2D(outer.right(), inner.bottom()),
+        QVector2D(outer.right(), outer.bottom()),
+        QVector2D(outer.right(), outer.bottom()),
+        QVector2D(outer.left(), outer.bottom()),
+        QVector2D(outer.left(), inner.bottom()),
+        // left
+        QVector2D(outer.left(), inner.top()),
+        QVector2D(inner.left(), inner.top()),
+        QVector2D(inner.left(), inner.bottom()),
+        QVector2D(inner.left(), inner.bottom()),
+        QVector2D(outer.left(), inner.bottom()),
+        QVector2D(outer.left(), inner.top()),
+        // right
+        QVector2D(inner.right(), inner.top()),
+        QVector2D(outer.right(), inner.top()),
+        QVector2D(outer.right(), inner.bottom()),
+        QVector2D(outer.right(), inner.bottom()),
+        QVector2D(inner.right(), inner.bottom()),
+        QVector2D(inner.right(), inner.top()),
+    };
+
+    GLVertexBuffer *vbo = GLVertexBuffer::streamingBuffer();
+    vbo->reset();
+    vbo->setVertices(verts);
+
+    ShaderBinder binder(ShaderTrait::UniformColor);
+    binder.shader()->setUniform(GLShader::Mat4Uniform::ModelViewProjectionMatrix, viewport.projectionMatrix());
+    binder.shader()->setUniform(GLShader::ColorUniform::Color, color);
+    vbo->render(GL_TRIANGLES);
+}
+
 bool ColorPickerEffect::supported()
 {
     return effects->isOpenGLCompositing();
@@ -64,6 +113,13 @@ ColorPickerEffect::ColorPickerEffect()
 {
     qDBusRegisterMetaType<QColor>();
     QDBusConnection::sessionBus().registerObject(QStringLiteral("/ColorPicker"), this, QDBusConnection::ExportScriptableContents);
+
+    connect(effects, &EffectsHandler::mouseChanged, this, [this](const QPointF &pos, const QPointF &oldPos) {
+        if (isActive() && pos != oldPos) {
+            effects->addRepaint(loupeArea(oldPos).united(loupeArea(pos)));
+        }
+    });
+    connect(effects, &EffectsHandler::screenLockingChanged, this, &ColorPickerEffect::updateCursor);
 }

 ColorPickerEffect::~ColorPickerEffect()
@@ -160,10 +216,94 @@ void ColorPickerEffect::setPicking(bool picking)
 {
     if (m_picking != picking) {
         m_picking = picking;
+        updateCursor();
+        effects->addRepaint(loupeArea(effects->cursorPos()));
         Q_EMIT effects->colorPickerActiveChanged();
     }
 }

+void ColorPickerEffect::updateCursor()
+{
+    // The loupe replaces the cursor, so that it doesn't cover the pixel being picked
+    const bool hide = isActive();
+    if (m_cursorHidden != hide) {
+        m_cursorHidden = hide;
+        if (hide) {
+            effects->hideCursor();
+        } else {
+            effects->showCursor();
+        }
+    }
+}
+
+Rect ColorPickerEffect::loupeArea(const QPointF &pos) const
+{
+    const int size = (2 * s_loupeRadius + 1) * s_loupeCellSize;
+    const QPoint pixel(std::floor(pos.x()), std::floor(pos.y()));
+    return Rect(pixel.x() - size / 2, pixel.y() - size / 2, size, size).adjusted(-2, -2, 2, 2);
+}
+
+void ColorPickerEffect::prePaintScreen(ScreenPrePaintData &data)
+{
+    effects->prePaintScreen(data);
+    data.paint += loupeArea(effects->cursorPos());
+}
+
+bool ColorPickerEffect::paintScreen(const RenderTarget &renderTarget, const RenderViewport &viewport, int mask, const Region &deviceRegion, LogicalOutput *screen)
+{
+    if (!effects->paintScreen(renderTarget, viewport, mask, deviceRegion, screen)) {
+        return false;
+    }
+
+    const QPointF cursor = effects->cursorPos();
+    if (effects->screenAt(cursor.toPoint()) != screen) {
+        return true;
+    }
+
+    const qreal scale = viewport.scale();
+    const int cells = 2 * s_loupeRadius + 1;
+    const QPoint pixel(std::floor(cursor.x()), std::floor(cursor.y()));
+    const Rect source(pixel.x() - s_loupeRadius, pixel.y() - s_loupeRadius, cells, cells);
+    const Rect clippedSource = source.intersected(screen->geometry());
+    if (clippedSource.isEmpty()) {
+        return true;
+    }
+
+    const auto texture = GLTexture::allocate(GL_RGBA8, QSize(std::ceil(cells * scale), std::ceil(cells * scale)));
+    if (!texture) {
+        return true;
+    }
+    texture->setFilter(GL_NEAREST);
+    texture->setWrapMode(GL_CLAMP_TO_EDGE);
+    GLFramebuffer framebuffer(texture.get());
+    if (!framebuffer.valid()) {
+        return true;
+    }
+
+    // Parts of the source area outside of the screen are shown as black
+    GLFramebuffer::pushFramebuffer(&framebuffer);
+    glClearColor(0, 0, 0, 1);
+    glClear(GL_COLOR_BUFFER_BIT);
+    GLFramebuffer::popFramebuffer();
+    framebuffer.blitFromRenderTarget(renderTarget, viewport, clippedSource,
+                                     RectF(clippedSource.translated(-source.topLeft())).scaled(scale).rounded());
+
+    const Rect area = loupeArea(cursor).adjusted(2, 2, -2, -2);
+    auto shader = ShaderManager::instance()->pushShader(ShaderTrait::MapTexture);
+    QMatrix4x4 mvp = viewport.projectionMatrix();
+    mvp.translate(area.x() * scale, area.y() * scale);
+    shader->setUniform(GLShader::Mat4Uniform::ModelViewProjectionMatrix, mvp);
+    texture->render(area.size() * scale);
+    ShaderManager::instance()->popShader();
+
+    const RectF center(area.x() + s_loupeRadius * s_loupeCellSize, area.y() + s_loupeRadius * s_loupeCellSize, s_loupeCellSize, s_loupeCellSize);
+    renderOutline(viewport, RectF(area).adjusted(-2, -2, 2, 2), 1, Qt::black);
+    renderOutline(viewport, RectF(area).adjusted(-1, -1, 1, 1), 1, Qt::white);
+    renderOutline(viewport, center.adjusted(-1, -1, 1, 1), 1, Qt::black);
+    renderOutline(viewport, center, 1, Qt::white);
+    return true;
+}
+
 bool ColorPickerEffect::isActive() const
 {
     return m_picking && !effects->isScreenLocked();
diff --git a/src/plugins/colorpicker/colorpicker.h b/src/plugins/colorpicker/colorpicker.h
index 8a97550558..cb5c8784ca 100644
--- a/src/plugins/colorpicker/colorpicker.h
+++ b/src/plugins/colorpicker/colorpicker.h
@@ -28,6 +28,9 @@ public:
     ~ColorPickerEffect() override;
     bool isActive() const override;

+    void prePaintScreen(ScreenPrePaintData &data) override;
+    bool paintScreen(const RenderTarget &renderTarget, const RenderViewport &viewport, int mask, const Region &deviceRegion, LogicalOutput *screen) override;
+
     int requestedEffectChainPosition() const override
     {
         return 0;
@@ -42,9 +45,12 @@ private:
     void showInfoMessage();
     void hideInfoMessage();
     void setPicking(bool picking);
+    void updateCursor();
+    Rect loupeArea(const QPointF &pos) const;

     QDBusMessage m_replyMessage;
     bool m_picking = false;
+    bool m_cursorHidden = false;
 };

 } // namespace
